// Pre-bundled Bible chapters (offline from install)
(function(){
  var bundles={};
  bundles['KJV_43_3']=[{"n": 1, "t": "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"}, {"n": 2, "t": "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."}, {"n": 3, "t": "Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God."}, {"n": 4, "t": "Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother's womb, and be born?"}, {"n": 5, "t": "Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God."}, {"n": 6, "t": "That which is born of the flesh is flesh; and that which is born of the Spirit is spirit."}, {"n": 7, "t": "Marvel not that I said unto thee, Ye must be born again."}, {"n": 8, "t": "The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit."}, {"n": 9, "t": "Nicodemus answered and said unto him, How can these things be?"}, {"n": 10, "t": "Jesus answered and said unto him, Art thou a master of Israel, and knowest not these things?"}, {"n": 11, "t": "Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness."}, {"n": 12, "t": "If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things?"}, {"n": 13, "t": "And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven."}, {"n": 14, "t": "And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:"}, {"n": 15, "t": "That whosoever believeth in him should not perish, but have eternal life."}, {"n": 16, "t": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."}, {"n": 17, "t": "For God sent not his Son into the world to condemn the world; but that the world through him might be saved."}, {"n": 18, "t": "He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God."}, {"n": 19, "t": "And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil."}, {"n": 20, "t": "For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved."}, {"n": 21, "t": "But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God."}, {"n": 22, "t": "After these things came Jesus and his disciples into the land of Judaea; and there he tarried with them, and baptized."}, {"n": 23, "t": "And John also was baptizing in Aenon near to Salim, because there was much water there: and they came, and were baptized."}, {"n": 24, "t": "For John was not yet cast into prison."}, {"n": 25, "t": "Then there arose a question between some of John's disciples and the Jews about purifying."}, {"n": 26, "t": "And they came unto John, and said unto him, Rabbi, he that was with thee beyond Jordan, to whom thou barest witness, behold, the same baptizeth, and all men come to him."}, {"n": 27, "t": "John answered and said, A man can receive nothing, except it be given him from heaven."}, {"n": 28, "t": "Ye yourselves bear me witness, that I said, I am not the Christ, but that I am sent before him."}, {"n": 29, "t": "He that hath the bride is the bridegroom: but the friend of the bridegroom, which standeth and heareth him, rejoiceth greatly because of the bridegroom's voice: this my joy therefore is fulfilled."}, {"n": 30, "t": "He must increase, but I must decrease."}, {"n": 31, "t": "He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all."}, {"n": 32, "t": "And what he hath seen and heard, that he testifieth; and no man receiveth his testimony."}, {"n": 33, "t": "He that hath received his testimony hath set to his seal that God is true."}, {"n": 34, "t": "For he whom God hath sent speaketh the words of God: for God giveth not the Spirit by measure unto him."}, {"n": 35, "t": "The Father loveth the Son, and hath given all things into his hand."}, {"n": 36, "t": "He that believeth on the Son hath everlasting life: and he that believeth not the Son shall not see life; but the wrath of God abideth on him."}];
  bundles['KJV_19_23']=[{"n": 1, "t": "The LORD is my shepherd; I shall not want."}, {"n": 2, "t": "He maketh me to lie down in green pastures: he leadeth me beside the still waters."}, {"n": 3, "t": "He restoreth my soul: he leadeth me in the paths of righteousness for his name's sake."}, {"n": 4, "t": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."}, {"n": 5, "t": "Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over."}, {"n": 6, "t": "Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever."}];
  bundles['KJV_43_1']=[{"n": 1, "t": "In the beginning was the Word, and the Word was with God, and the Word was God."}, {"n": 2, "t": "The same was in the beginning with God."}, {"n": 3, "t": "All things were made by him; and without him was not any thing made that was made."}, {"n": 4, "t": "In him was life; and the life was the light of men."}, {"n": 5, "t": "And the light shineth in darkness; and the darkness comprehended it not."}, {"n": 6, "t": "There was a man sent from God, whose name was John."}, {"n": 7, "t": "The same came for a witness, to bear witness of the Light, that all men through him might believe."}, {"n": 8, "t": "He was not that Light, but was sent to bear witness of that Light."}, {"n": 9, "t": "That was the true Light, which lighteth every man that cometh into the world."}, {"n": 10, "t": "He was in the world, and the world was made by him, and the world knew him not."}, {"n": 11, "t": "He came unto his own, and his own received him not."}, {"n": 12, "t": "But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:"}, {"n": 13, "t": "Which were born, not of blood, nor of the will of the flesh, nor of the will of man, but of God."}, {"n": 14, "t": "And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth."}, {"n": 15, "t": "John bare witness of him, and cried, saying, This was he of whom I spake, He that cometh after me is preferred before me: for he was before me."}, {"n": 16, "t": "And of his fulness have all we received, and grace for grace."}, {"n": 17, "t": "For the law was given by Moses, but grace and truth came by Jesus Christ."}, {"n": 18, "t": "No man hath seen God at any time; the only begotten Son, which is in the bosom of the Father, he hath declared him."}, {"n": 19, "t": "And this is the record of John, when the Jews sent priests and Levites from Jerusalem to ask him, Who art thou?"}, {"n": 20, "t": "And he confessed, and denied not; but confessed, I am not the Christ."}, {"n": 21, "t": "And they asked him, What then? Art thou Elias? And he saith, I am not. Art thou that prophet? And he answered, No."}, {"n": 22, "t": "Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?"}, {"n": 23, "t": "He said, I am the voice of one crying in the wilderness, Make straight the way of the Lord, as said the prophet Esaias."}, {"n": 24, "t": "And they which were sent were of the Pharisees."}, {"n": 25, "t": "And they asked him, and said unto him, Why baptizest thou then, if thou be not that Christ, nor Elias, neither that prophet?"}, {"n": 26, "t": "John answered them, saying, I baptize with water: but there standeth one among you, whom ye know not;"}, {"n": 27, "t": "He it is, who coming after me is preferred before me, whose shoe's latchet I am not worthy to unloose."}, {"n": 28, "t": "These things were done in Bethabara beyond Jordan, where John was baptizing."}, {"n": 29, "t": "The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world."}, {"n": 30, "t": "This is he of whom I said, After me cometh a man which is preferred before me: for he was before me."}, {"n": 31, "t": "And I knew him not: but that he should be made manifest to Israel, therefore am I come baptizing with water."}, {"n": 32, "t": "And John bare record, saying, I saw the Spirit descending from heaven like a dove, and it abode upon him."}, {"n": 33, "t": "And I knew him not: but he that sent me to baptize with water, the same said unto me, Upon whom thou shalt see the Spirit descending, and remaining on him, the same is he which baptizeth with the Holy Ghost."}, {"n": 34, "t": "And I saw, and bare record that this is the Son of God."}, {"n": 35, "t": "Again the next day after John stood, and two of his disciples;"}, {"n": 36, "t": "And looking upon Jesus as he walked, he saith, Behold the Lamb of God!"}, {"n": 37, "t": "And the two disciples heard him speak, and they followed Jesus."}, {"n": 38, "t": "Then Jesus turned, and saw them following, and saith unto them, What seek ye? They said unto him, Rabbi, (which is to say, being interpreted, Master,) where dwellest thou?"}, {"n": 39, "t": "He saith unto them, Come and see. They came and saw where he dwelt, and abode with him that day: for it was about the tenth hour."}, {"n": 40, "t": "One of the two which heard John speak, and followed him, was Andrew, Simon Peter's brother."}, {"n": 41, "t": "He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ."}, {"n": 42, "t": "And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone."}, {"n": 43, "t": "The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me."}, {"n": 44, "t": "Now Philip was of Bethsaida, the city of Andrew and Peter."}, {"n": 45, "t": "Philip findeth Nathanael, and saith unto him, We have found him, of whom Moses in the law, and the prophets, did write, Jesus of Nazareth, the son of Joseph."}, {"n": 46, "t": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}, {"n": 47, "t": "Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!"}, {"n": 48, "t": "Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee."}, {"n": 49, "t": "Nathanael answered and saith unto him, Rabbi, thou art the Son of God; thou art the King of Israel."}, {"n": 50, "t": "Jesus answered and said unto him, Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these."}, {"n": 51, "t": "And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man."}];
  bundles['OVR_43_3']=[{"n": 1, "t": "பரிசேயரில் நிக்கோதேமு என்னும் பேரையுடைய மனுஷன் ஒருவன் இருந்தான், அவன் யூதருக்கு அதிபதியாயிருந்தான்."}, {"n": 2, "t": "தேவன் உம்முடனே இருக்காவிட்டால் நீர் செய்கிற இந்த அற்புதங்களை ஒருவனும் செய்யமாட்டான் என்று அறிந்திருக்கிறோம்; ஆகையால் நீர் தேவனிடத்திலிருந்து வந்த போதகர் என்று அறிந்திருக்கிறோம் என்று இராத்திரிகாலத்தில் அவரிடத்தில் வந்து சொன்னான்."}, {"n": 3, "t": "இயேசு அவனுக்கு பிரதியுத்தரமாக: மறுபடியும் பிறவாவிட்டால் தேவனுடைய ராஜ்யத்தை ஒருவனும் காணமாட்டான் என்று மெய்யாகவே மெய்யாகவே உனக்குச் சொல்லுகிறேன் என்றார்."}, {"n": 4, "t": "நிக்கோதேமு அவரை நோக்கி: மனுஷன் முதிர்வயதாயிருக்கும்போது எப்படிப் பிறப்பான்? தன் தாயின் கர்ப்பத்தில் இரண்டாந்தரம் பிரவேசித்துப் பிறக்கலாமா என்று கேட்டான்."}, {"n": 5, "t": "இயேசு பிரதியுத்தரமாக: ஒருவன் ஜலத்தினாலும் ஆவியினாலும் பிறவாவிட்டால் தேவனுடைய ராஜ்யத்தில் பிரவேசிக்கமாட்டான் என்று மெய்யாகவே மெய்யாகவே உனக்குச் சொல்லுகிறேன்."}, {"n": 6, "t": "மாம்சத்தினால் பிறப்பது மாம்சமாயிருக்கும்; ஆவியினால் பிறப்பது ஆவியாயிருக்கும்."}, {"n": 7, "t": "நீ மறுபடியும் பிறக்கவேண்டும் என்று நான் உனக்குச் சொன்னதைக்குறித்து ஆச்சரியப்படாதே."}, {"n": 8, "t": "காற்று தனக்கு இஷ்டமானபோக்கிலே வீசுகிறது, அதின் சத்தத்தை நீ கேட்கிறாய்; ஆகிலும் அது எங்கிருந்து வருகிறதென்றும் எங்கே போகிறதென்றும் உனக்குத் தெரியாது; ஆவியினால் பிறந்த எவனும் இப்படியே இருக்கிறான் என்றார்."}, {"n": 9, "t": "நிக்கோதேமு அவரை நோக்கி: இவை எப்படி ஆகும் என்று கேட்டான்."}, {"n": 10, "t": "இயேசு அவனுக்கு பிரதியுத்தரமாக: நீ இஸ்ரவேலில் போதகனாயிருந்தும் இவைகளை அறியாமலிருக்கிறாயா என்றார்."}, {"n": 11, "t": "நாங்கள் அறிந்திருக்கிறதைச் சொல்லுகிறோம், கண்டிருக்கிறதற்கு சாட்சிகொடுக்கிறோம், ஆகிலும் நீங்கள் எங்கள் சாட்சியை ஏற்றுக்கொள்வதில்லை என்று மெய்யாகவே மெய்யாகவே உனக்குச் சொல்லுகிறேன்."}, {"n": 12, "t": "நான் உங்களுக்கு பூமிக்குரிய காரியங்களைச் சொன்னபோது நம்பாமற்போனீர்கள், பரலோகத்துக்குரிய காரியங்களைச் சொன்னால் நம்புவீர்களா?"}, {"n": 13, "t": "பரலோகத்திலிருந்து இறங்கினவரும் பரலோகத்தில் இருக்கிறவருமான மனுஷகுமாரனேயன்றி வேறொருவனும் பரலோகத்திற்கு ஏறினதில்லை."}, {"n": 14, "t": "மோசே வனாந்தரத்திலே பாம்பை உயர்த்தினதுபோல மனுஷகுமாரனும் உயர்த்தப்படவேண்டும்."}, {"n": 15, "t": "அவரில் விசுவாசமாயிருக்கிற எவனும் கெட்டுப்போகாமல் நித்தியஜீவனை அடையும்படிக்கே."}, {"n": 16, "t": "தேவன் தம்முடைய ஒரேபேறான குமாரனை விசுவாசிக்கிறவன் எவனும் கெட்டுப்போகாமல் நித்தியஜீவனை அடையும்படிக்கு, அவரை அனுப்பும்வரைக்கும் உலகத்தில் அன்பு கூர்ந்தார்."}, {"n": 17, "t": "தேவன் தம்முடைய குமாரனை உலகத்தை ஆக்கினைக்குள்ளாக தீர்க்கும்படி அல்ல, அவராலே உலகம் இரட்சிக்கப்படும்படிக்கே உலகத்தில் அனுப்பினார்."}, {"n": 18, "t": "அவரில் விசுவாசமாயிருக்கிறவன் ஆக்கினைக்குள்ளாகத் தீர்க்கப்படான்; விசுவாசமாயிராதவனோ தேவனுடைய ஒரேபேறான குமாரனுடைய நாமத்தில் விசுவாசமாயிராதபடியினால் ஏற்கனவே ஆக்கினைக்குள்ளாகத் தீர்க்கப்பட்டிருக்கிறான்."}, {"n": 19, "t": "அந்த ஆக்கினைத்தீர்ப்பு என்னவெனில்: வெளிச்சம் உலகத்தில் வந்திருக்கிறது, ஆகிலும் மனுஷரின் கிரியைகள் பொல்லாதவைகளாயிருந்தபடியால் அவர்கள் வெளிச்சத்தைப்பார்க்கிலும் இருளை விரும்பினார்கள்."}, {"n": 20, "t": "பொல்லாங்கு செய்கிற எவனும் வெளிச்சத்தை வெறுக்கிறான், தன் கிரியைகள் கண்டிக்கப்படாதிருக்கும்படிக்கு வெளிச்சத்தினிடத்தில் வரமாட்டான்."}, {"n": 21, "t": "உண்மையைச் செய்கிறவனோ, தன் கிரியைகள் தேவனுக்கு இயைந்தவைகள் என்று வெளிப்படும்படிக்கு, வெளிச்சத்தினிடத்தில் வருகிறான்."}, {"n": 22, "t": "இவைகளுக்குப் பிறகு இயேசுவும் அவருடைய சீஷர்களும் யூதேயாதேசத்திற்குள் வந்தார்கள்; அங்கே அவர்களோடேகூட தங்கி ஞானஸ்நானம் கொடுத்தார்."}, {"n": 23, "t": "யோவான் சாலேமுக்கு அருகிலிருக்கிற ஏனோனிலே ஞானஸ்நானம் கொடுத்துக்கொண்டிருந்தான், அவ்விடத்தில் தண்ணீர் மிகுதியாயிருந்தது; அங்கே மக்கள் வந்து ஞானஸ்நானம் பெற்றார்கள்."}, {"n": 24, "t": "அப்பொழுது யோவான் சிறைப்பட்டிருக்கவில்லை."}, {"n": 25, "t": "அப்பொழுது யோவானுடைய சீஷர்களும் யூதர்களும் தூய்மையாக்குதலைக்குறித்து தங்களுக்குள் வாக்குவாதம்பண்ணினார்கள்."}, {"n": 26, "t": "அவர்கள் யோவானிடத்தில் வந்து: ரபி, யோர்தானுக்கு அப்புறத்தில் உம்மோடு இருந்தவரைக்குறித்தும் நீர் சாட்சிகொடுத்தவரைக்குறித்தும் சொல்லுகிறேன்; இதோ, அவர் ஞானஸ்நானம் கொடுக்கிறார், எல்லாரும் அவரிடத்தில் போகிறார்கள் என்றார்கள்."}, {"n": 27, "t": "யோவான் அவர்களுக்குப் பிரதியுத்தரமாக: ஒருவனும் பரலோகத்திலிருந்து தனக்கு ஒன்றும் கொடுக்கப்படாவிட்டால் ஒன்றையும் பெற்றுக்கொள்ள மாட்டான்."}, {"n": 28, "t": "நான் கிறிஸ்து அல்ல, ஆகிலும் நான் அவருக்கு முன்னே அனுப்பப்பட்டவன் என்று நான் சொன்னதற்கு நீங்களே சாட்சிகள்."}, {"n": 29, "t": "மணவாட்டியை உடையவன் மணவாளன்; மணவாளனுடைய சிநேகிதனோ நின்று, மணவாளனுடைய சத்தத்தை கேட்கும்போது மிகவும் சந்தோஷப்படுகிறான்; எனக்கு இந்த சந்தோஷம் நிறைவேறியிருக்கிறது."}, {"n": 30, "t": "அவர் வளரவேண்டும், நான் குறையவேண்டும்."}, {"n": 31, "t": "மேலிருந்து வருகிறவர் எல்லாருக்கும் மேலானவர்; பூமியிலிருந்து உண்டானவன் பூமியினுடையவன், பூமியைக்குறித்துப் பேசுகிறான்; பரலோகத்திலிருந்து வருகிறவர் எல்லாருக்கும் மேலானவர்."}, {"n": 32, "t": "தாம் கண்டதையும் கேட்டதையும் சாட்சியாக சொல்லுகிறார், ஆகிலும் அவருடைய சாட்சியை ஒருவனும் ஏற்றுக்கொள்வதில்லை."}, {"n": 33, "t": "அவருடைய சாட்சியை ஏற்றுக்கொண்டவன் தேவன் உண்மையுள்ளவர் என்று முத்திரை போட்டிருக்கிறான்."}, {"n": 34, "t": "தேவன் அனுப்பினவர் தேவனுடைய வார்த்தைகளைப் பேசுகிறார், தேவன் ஆவியை அளவில்லாமல் கொடுக்கிறார்."}, {"n": 35, "t": "பிதா குமாரனில் அன்பாயிருந்து, எல்லாவற்றையும் அவர் கையில் ஒப்புக்கொடுத்திருக்கிறார்."}, {"n": 36, "t": "குமாரனில் விசுவாசமாயிருக்கிறவனுக்கு நித்தியஜீவன் உண்டு; குமாரனை விசுவாசியாதவனோ ஜீவனைக் காண்பதில்லை, தேவனுடைய கோபாக்கினை அவன்மேல் தங்கியிருக்கிறது."}];
  bundles['OVR_19_23']=[{"n": 1, "t": "கர்த்தர் என் மேய்ப்பர், எனக்கு குறைவிராது."}, {"n": 2, "t": "பசும்புல் வெளிகளில் என்னை மேய்வித்து, தண்ணீர் ஓடைகளண்டையில் என்னை நடத்துகிறார்."}, {"n": 3, "t": "என் ஆத்துமாவை தேற்றி, தம்முடைய நாமத்தினிமித்தம் நீதியின் பாதைகளில் என்னை நடத்துகிறார்."}, {"n": 4, "t": "மரண இருளின் பள்ளத்தாக்கில் நடந்தாலும் தீமைக்கு பயப்படேன், நீர் என்னோடு இருக்கிறீர்; உம்முடைய தண்டும் உம்முடைய கோலும் என்னை தேற்றுகின்றன."}, {"n": 5, "t": "என் சத்துருக்கள் முன்பாக எனக்கு பந்தி போட்டு, என் தலையை எண்ணெயால் அபிஷேகம்பண்ணுகிறீர்; என் பாத்திரம் நிரம்பி வழிகிறது."}, {"n": 6, "t": "நிச்சயமாய் என் ஜீவனுள்ள நாளெல்லாம் நன்மையும் கிருபையும் என்னைப் பின் தொடரும், கர்த்தருடைய வீட்டில் நீடிய நாள் வாசம்பண்ணுவேன்."}];
  bundles['OVR_43_1']=[{"n": 1, "t": "ஆதியிலே வார்த்தை இருந்தது, அந்த வார்த்தை தேவனிடத்திலிருந்தது, அந்த வார்த்தை தேவனாயிருந்தது."}, {"n": 2, "t": "ஆதியிலே அவர் தேவனிடத்திலிருந்தார்."}, {"n": 3, "t": "எல்லாம் அவர் மூலமாய் உண்டாயிற்று, உண்டானதொன்றும் அவராலே அல்லாமல் உண்டாகவில்லை."}, {"n": 4, "t": "அவரில் ஜீவன் இருந்தது, அந்த ஜீவன் மனுஷருக்கு வெளிச்சமாயிருந்தது."}, {"n": 5, "t": "வெளிச்சம் இருளிலே பிரகாசிக்கிறது, இருள் அதை பற்றிக்கொள்ளவில்லை."}, {"n": 6, "t": "தேவனால் அனுப்பப்பட்ட ஒரு மனுஷன் இருந்தான், அவன் பேர் யோவான்."}, {"n": 7, "t": "எல்லாரும் தன்னாலே விசுவாசிக்கும்படிக்கு அவன் வெளிச்சத்திற்கு சாட்சியாக சாட்சிகொடுக்க வந்தான்."}, {"n": 8, "t": "அவன் வெளிச்சமல்ல, வெளிச்சத்திற்கு சாட்சிகொடுக்க அனுப்பப்பட்டவன்."}, {"n": 9, "t": "உலகத்தில் வருகிற எந்த மனுஷனுக்கும் வெளிச்சமாகிற மெய்யான வெளிச்சம் அது."}, {"n": 10, "t": "அவர் உலகத்தில் இருந்தார், உலகம் அவராலே உண்டாயிற்று, உலகம் அவரை அறியவில்லை."}, {"n": 11, "t": "தம்முடைய சொந்தமானவர்களிடத்தில் வந்தார், அவருடையவர்கள் அவரை ஏற்றுக்கொள்ளவில்லை."}, {"n": 12, "t": "அவரை ஏற்றுக்கொண்டவர்கள் எத்தனைபேரோ, அவர்கள் தம்முடைய நாமத்தின்மேல் விசுவாசமாயிருக்கிறவர்களாகிய அவர்களுக்கு தேவனுடைய பிள்ளைகளாகும் பாக்கியத்தை கொடுத்தார்."}, {"n": 13, "t": "அவர்கள் இரத்தத்தினாலும் மாம்சத்தின் சித்தத்தினாலும் புருஷனுடைய சித்தத்தினாலும் அல்ல, தேவனாலே பிறந்தார்கள்."}, {"n": 14, "t": "வார்த்தை மாம்சமாகி, கிருபையும் சத்தியமும் நிறைந்தவராய் நம்மிடையே வாசம்பண்ணினார், பிதாவினால் ஒரே பேறான குமாரனுடைய மகிமைக்கு ஏற்ற மகிமையை அவருக்கு கண்டோம்."}, {"n": 15, "t": "யோவான் அவரைக்குறித்து சாட்சிகொடுத்து, என்னிடத்திலிருந்து வருகிறவர் என்னிலும் மேம்பட்டவர், என்னிலும் முன்னிருந்தவர் என்று, என்னிடத்தில் பின்னே வருகிறவர் என்னிலும் முன்னிருந்தவர் என்று நான் சொன்னது இவரையே என்று உரத்த சத்தமாய் கூறி சாட்சிகொடுத்தான்."}, {"n": 16, "t": "அவருடைய நிறைவினால் நாம் எல்லாரும் கிருபைமேல் கிருபை பெற்றோம்."}, {"n": 17, "t": "நியாயப்பிரமாணம் மோசேயினால் கொடுக்கப்பட்டது, கிருபையும் சத்தியமும் இயேசுகிறிஸ்துவினால் உண்டாயிற்று."}, {"n": 18, "t": "தேவனை ஒருவனும் ஒருக்காலும் கண்டதில்லை, பிதாவின் மடியிலிருக்கிற ஒரேபேறான குமாரன் அவரை வெளிப்படுத்தினார்."}];
  for(var k in bundles){
    try{
      var lk='bible_'+k;
      if(!localStorage.getItem(lk)){
        localStorage.setItem(lk, JSON.stringify(bundles[k]));
      }
    }catch(e){}
  }
})();
